/**
 * ai-overview.js — shared "Overview by AI" (#196) engine.
 *
 * A short prose orientation (2–4 paragraphs), generated by running the
 * selected cloud model (Claude, OpenAI, or Gemini) AGENTICALLY over
 * CodeExam's own MCP tools: the model follows the orientation path in
 * AI_OVERVIEW_PROMPT, calling mcp__code-exam__* against the target index.
 *
 * Runs over the Anthropic SDK — no `claude` CLI dependency (#196). It spawns
 * CodeExam's own mcp-server (src/mcp-server.js) as a subprocess, connects an
 * in-process MCP client, and drives the tool-use loop itself (the same pattern
 * the chat web-app uses). Cost is summed per turn via core/pricing.js. The
 * local-LLM path lives in ai-overview-local.js.
 *
 * Shared by the GUI route (src/server.js `/api/ai-overview`) and the CLI
 * command (src/index.js `--overview-by-ai`) so the prompt + tool allow-list +
 * loop can't drift between the two surfaces. The flow/prompt were validated
 * across six diverse indexes.
 */

import path from 'path';
import { fileURLToPath } from 'url';
import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';
import { estimateCost } from './pricing.js';
import { assertLocalOnly, isLocalApiUrl } from './air-gapped.js';
import { openaiCompletionBudget } from './openai-util.js';
import { PROVIDERS } from './providers.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url)); // src/core
const MCP_SERVER = path.join(__dirname, '..', 'mcp-server.js');  // src/mcp-server.js

// The MCP tools the model is allowed to call — kept deliberately tight to the
// orientation path; digest/vocabulary/models_used are skipped by the model
// itself on minified targets (see prompt step 1). AI_OVERVIEW_TOOL_NAMES are the
// bare names (used to filter the SDK tool list); AI_OVERVIEW_TOOLS is the
// `mcp__code-exam__`-prefixed comma-joined form, kept for back-compat.
export const AI_OVERVIEW_TOOL_NAMES = [
  'overview', 'vocabulary', 'digest', 'stats', 'list_files', 'list_classes',
  'entry_points', 'hotspots', 'models_used', 'command_catalog', 'regex_search',
  'search', 'call_tree', 'struct_dupes', 'show_file', 'referenced_resources',
];
export const AI_OVERVIEW_TOOLS = AI_OVERVIEW_TOOL_NAMES.map(t => `mcp__code-exam__${t}`).join(',');

export const AI_OVERVIEW_PROMPT = `You are orienting a code examiner to an unfamiliar codebase using the CodeExam MCP tools (mcp__code-exam__*) over the currently-loaded index. Produce a SHORT prose orientation — 2-4 short paragraphs (NOT one long block, NOT bullet lists), then the two labeled lists at the end. Budget: ~5-8 tool calls; do not exceed ~5 digests.

STYLE — read first:
- Write about the CODEBASE, not about CodeExam. If a CE signal is misleading, quietly reach the right answer and state it as a plain fact about the code — do NOT narrate CE's mechanics. Say "<subsystem> is <what it actually is>", NOT "CE's <signal> is misleading here — it's actually <role>" — angle brackets are slots to fill from this index, never words to emit. The reader cares about the code they're about to examine, not how the overview corrects CE's low-level signals.
- Vary your wording; don't lean on stock phrases or a fixed template. Reach for a framing (e.g. "a layer over two systems", "host vs vendored", "the spine"/"center of gravity") ONLY when this codebase genuinely fits it — never force it onto every index.
- Be terse on trouble: if a tool errors, the index is empty/minified/unreachable, or something is a CE indexing artifact, note it in ONE sentence and move on. NEVER write a troubleshooting log, ask the reader a question, or leak your own process ("I now have a complete picture…"). If you truly cannot orient (no tools reachable / empty index), output a single line saying so and stop.
- Output ONLY the overview; no preamble.

1. DETECT THE TARGET'S SHAPE FIRST — call overview, then stats. Then choose a path:
   - Minified/bundled or binary-dominated (minified module names, .node/binary symbols like napi_*, huge per-file function counts): lead with command_catalog and regex_search on distinctive strings; do NOT call digest/vocabulary/models_used (they fail on minified code).
   - A collection (CE flags >=2 substantial top-level folders): say so in one sentence, then orient PER-REPO with list_files <repo>/. Don't belabor that it isn't one project — and sanity-check the flag, since a high line count dominated by data/logs/markdown is not a multi-repo collection.
   - Readable single project: overview -> vocabulary -> digest the top 3-5 key files (stop at ~5) -> models_used. command_catalog for a CLI/route app; regex_search for internal protocols/routes (e.g. /api/ or other prefixes you observe); call_tree from an entry point for control flow. referenced_resources for the external surface (env vars, hosts/URLs, embedded SQL, external commands, data/config files); if one data/config file dominates by reference count, name it (use the counts, don't assume).
   - Read the README/conventions for product framing if present (show_file on README*, CLAUDE.md, AGENTS.md).

2. When there IS vendored/bundled dependency code, separate it from the host app — density-ranked signals point at the biggest dependency, not the host. Skip this entirely if nothing is vendored.

3. Recognize CE's own artifacts SILENTLY (.op = CE binary-string captures, zip!-prefixed paths = archive members, single-letter names = expected in minified bundles). They're not findings — don't explain them to the reader unless one is genuinely load-bearing.

4. Include ONE AI/ML sentence from models_used: detected (name them, api vs local — but at most a couple, and flag obviously-example IDs as examples; don't enumerate a suspect list), none detected, or inconclusive (minified / var-held). Distrust models_used counts on minified code.

5. Treat naming/comments/docs as indicia, not ground truth — they drift and are often stale on active code. When a specific claim rests on a doc/name the code doesn't confirm, flag it briefly in passing; don't turn this into a ritual or a labeled two-column checklist.

6. Prefer evidence over speculation: instead of "almost certainly X — confirm with tool Y," just run Y within budget. Resolve anything you raise in the same breath, or drop it (no teasers). Use the signals CE computes across the whole corpus — clones (struct_dupes), structural centrality (hotspots), IDF vocabulary, the external surface, what-was-skipped — to say something a quick skim wouldn't, but keep it about the code.

OUTPUT (prose + two short labeled lists):
- The 2-4 short paragraphs (what it is, architecture, what it does, the AI/ML sentence).
- "Where to look first / highest-payback CE commands" — AT MOST 5 entries, each with one-line reasoning, including "skip X here" when a tool is defeated by the target.
- "Questions to start with" — AT MOST 5 entries, and give a MIX of surfaces: include 2-3 phrased for the GUI (e.g. "open the Functions accordion and filter for \`<term>\`", "ask the Chat pane about \`<topic>\`", "click \`<file>\` in the Files list") and 2 as CLI commands. Pair each with the single CE action/command that most DIRECTLY answers it (verify a structural claim with the confirming command — a clone claim uses struct_dupes --cross-source-only or list_files, not a bare struct_dupes). Directed exploration, not noodling.
Emit file/function references as backticked paths (\`path\` or \`path@func\`) so they can be made clickable.`;

// Grounding mode (#196, mirrors the chat's #36 clauses): how freely the overview
// may use knowledge beyond the indexed codebase. Default 'grounded' — forensic by
// default. (Chat keeps its own copy in server.js; a later cleanup can dedupe both
// into one shared module.)
export const AI_OVERVIEW_GROUNDING_CLAUSES = {
  grounded: `GROUNDING — STRICT: Base the overview ONLY on what the tools surface about this code. If something cannot be determined from the code, say so rather than filling the gap with general knowledge. Do NOT assert the purpose of a referenced library/algorithm, the research domain, or any external framing as fact about this codebase unless the code itself states it.`,
  augmented: `GROUNDING — AUGMENTED: You may combine what the tools surface with your general knowledge for the richest orientation — naming the domain or research area, explaining what a referenced library or algorithm does, and supplying standard context the code assumes its readers already know.`,
  attributed: `GROUNDING — ATTRIBUTED: Combine codebase evidence with general knowledge, but make provenance explicit — distinguish claims grounded in THIS code (cite the file/function/tool) from claims that come from your general knowledge or inference. Flag every non-trivial external claim as such.`,
};

// #276: local GGUF engines need explicit insistence that the tools are live —
// without it, smaller/laconic families (Gemma 3 observed) skip the tools and
// confidently invent a generic codebase. Cloud engines don't get this clause
// (they don't need it, and it wastes their context).
export const LOCAL_ENGINE_GROUNDING = `LOCAL-ENGINE GROUNDING (follow strictly): The source code IS available RIGHT NOW through the tools above — you have live access. NEVER answer from general knowledge and NEVER invent file names, counts, or model ids: every concrete claim MUST come from a tool result in THIS conversation. If you cannot call tools, output exactly "TOOLS UNAVAILABLE — cannot produce a grounded overview." and stop.`;

// AI_OVERVIEW_PROMPT + the selected grounding clause (default grounded);
// { localEngine: true } appends the local-engine insistence clause.
export function aiOverviewPrompt(grounding, { localEngine = false } = {}) {
  const clause = AI_OVERVIEW_GROUNDING_CLAUSES[grounding] || AI_OVERVIEW_GROUNDING_CLAUSES.grounded;
  return `${AI_OVERVIEW_PROMPT}\n\n${clause}${localEngine ? `\n\n${LOCAL_ENGINE_GROUNDING}` : ''}`;
}

/**
 * Run "Overview by AI" against an index directory over the Anthropic SDK.
 * Resolves with `{ prose, costUsd, usage }` or rejects with an Error whose
 * message is safe to surface to the user.
 *
 * Spawns CodeExam's mcp-server for the index, drives the agentic tool-use loop
 * over the SDK (tools restricted to AI_OVERVIEW_TOOL_NAMES), sums per-turn usage
 * into a cost via core/pricing.js, and enforces a spend ceiling + wall-clock
 * timeout. No `claude` CLI dependency.
 *
 * @param {object} opts
 * @param {string} opts.indexPath   Index directory to point the MCP server at (required).
 * @param {string} [opts.model]     Claude model id (default claude-sonnet-4-6).
 * @param {number} [opts.timeoutMs] Hard wall-clock limit (default 600000 = 10 min).
 * @param {string} [opts.grounding] Grounding mode (grounded | augmented | attributed).
 * @param {number} [opts.maxBudgetUsd] Hard spend ceiling (default CE_OVERVIEW_MAX_BUDGET env, else $5).
 * @param {(line:string)=>void} [opts.onStderr] Optional progress sink (tool-call + mcp-server stderr).
 * @returns {Promise<{prose:string, costUsd:(number|null), usage:(object|null)}>}
 */
const MAX_OVERVIEW_TURNS = 16;

export async function runAiOverview({ indexPath, engine = 'claude', model, apiKey, timeoutMs = 600000, grounding, maxBudgetUsd, onStderr } = {}) {
  if (!indexPath) throw new Error('runAiOverview: indexPath is required.');

  // Spend ceiling: explicit arg wins, else CE_OVERVIEW_MAX_BUDGET env, else $5.
  const _envBudget = parseFloat(process.env.CE_OVERVIEW_MAX_BUDGET);
  const budgetUsd = Number.isFinite(maxBudgetUsd) ? maxBudgetUsd
    : (Number.isFinite(_envBudget) ? _envBudget : 5.0);
  // #246: gemini rides the same openai-compat agentic branch as OpenAI.
  const _isCompat = engine === 'openai' || engine === 'gemini';
  const useModel = model || (engine === 'gemini'
    ? PROVIDERS.gemini.defaultModel
    : engine === 'openai'
    ? (process.env.CE_OPENAI_MODEL || 'gpt-5.1')
    : 'claude-sonnet-4-6');

  // Spawn CE's own mcp-server for this index and connect an in-process client.
  // Large indexes load synchronously at startup, so give the handshake the same
  // headroom the CLI path did via MCP_TIMEOUT.
  const transport = new StdioClientTransport({
    command: 'node',
    args: [MCP_SERVER, '--index-path', path.resolve(indexPath)],
    stderr: 'pipe',
    env: { ...process.env, MCP_TIMEOUT: String(timeoutMs + 60000) },
  });
  transport.stderr?.on('data', (d) => { if (onStderr) onStderr(`[mcp] ${d}`); });
  const mcpClient = new Client({ name: 'code-exam-overview', version: '1.0.0' }, {});
  const cleanup = async () => { try { await mcpClient.close(); } catch { /* ignore */ } };

  const loop = async () => {
    await mcpClient.connect(transport);
    const { tools } = await mcpClient.listTools();
    const allowed = new Set(AI_OVERVIEW_TOOL_NAMES);
    const sdkTools = tools
      .filter(t => allowed.has(String(t.name).split('__').pop()))
      .map(t => ({ name: t.name, description: t.description, input_schema: t.inputSchema }));
    if (!sdkTools.length) {
      throw new Error('AI Overview: no CodeExam MCP tools reachable (the mcp-server may have failed to start).');
    }

    // #223 air-gap is enforced per-engine below: the Claude branch blocks
    // unconditionally (the Anthropic SDK targets api.anthropic.com with no
    // loopback override), while the OpenAI branch allows a loopback
    // CE_OPENAI_API_URL — matching the chat/analyze surfaces, which the Overview
    // path previously did not (it hard-blocked a loopback endpoint here).

    // Shared per-tool executor: run one CE MCP tool, return its text.
    const runTool = async (name, args) => {
      if (onStderr) onStderr(`[overview] tool: ${name}\n`);
      try {
        const r = await mcpClient.callTool({ name, arguments: args });
        return { text: (r.content || []).filter(c => c.type === 'text').map(c => c.text).join('\n'), isError: false };
      } catch (e) {
        return { text: `Error: ${e.message}`, isError: true };
      }
    };
    const usage = { input_tokens: 0, output_tokens: 0 };
    const checkBudget = () => {
      const { usd } = estimateCost(useModel, usage);
      if (Number.isFinite(usd) && usd > budgetUsd) {
        throw new Error(`AI Overview hit the $${budgetUsd} spend cap. Raise it with CE_OVERVIEW_MAX_BUDGET=<amount> and retry, or narrow the index.`);
      }
    };
    let prose = '';

    if (_isCompat) {
      // #243B/#246: same agentic loop over the same mcp-server, OpenAI-compat
      // wire format (tool_calls / role:"tool") for OpenAI and Gemini alike;
      // plain HTTPS via global fetch. #246: baseUrl/key from the provider.
      const prov = PROVIDERS[engine];
      const apiUrl = process.env.CE_OPENAI_API_URL || `${prov.baseUrl}/chat/completions`;
      // #223: block a REMOTE endpoint under --air-gapped, but allow a loopback
      // CE_OPENAI_API_URL (e.g. LM Studio) — parity with chat/analyze. Checked
      // BEFORE the key check so an air-gapped run reports the air-gap reason
      // (parallel to the Claude branch), not a misleading "no API key".
      if (!isLocalApiUrl(apiUrl)) assertLocalOnly(`AI Overview (cloud ${prov.label})`);
      const key = apiKey || process.env[prov.keyEnv];
      if (!key) {
        throw new Error(`AI Overview needs a ${prov.label} key — set ${prov.keyEnv} (or ${prov.keyFiles[0]} / ${prov.keyFlag}), or run an air-gapped overview with a local --model <gguf>.`);
      }
      const oaTools = sdkTools.map(t => ({
        type: 'function',
        function: { name: t.name, description: t.description, parameters: t.input_schema || { type: 'object', properties: {} } },
      }));
      let messages = [{ role: 'user', content: aiOverviewPrompt(grounding) }];
      for (let turn = 0; turn < MAX_OVERVIEW_TURNS; turn++) {
        const resp = await fetch(apiUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${key}` },
          body: JSON.stringify({ model: useModel, max_completion_tokens: openaiCompletionBudget(useModel, 4096), messages, tools: oaTools }),
        });
        if (!resp.ok) throw new Error(`OpenAI API HTTP ${resp.status}: ${(await resp.text()).slice(0, 300)}`);
        const body = await resp.json();
        if (body.usage) {
          usage.input_tokens += body.usage.prompt_tokens || 0;
          usage.output_tokens += body.usage.completion_tokens || 0;
        }
        checkBudget();
        const msg = (body.choices && body.choices[0] && body.choices[0].message) || {};
        const text = String(msg.content || '').trim();
        if (text) prose = text;
        if (!Array.isArray(msg.tool_calls) || !msg.tool_calls.length) break;
        const toolMsgs = [];
        for (const tc of msg.tool_calls) {
          const rawArgs = (tc.function && tc.function.arguments) || '{}';
          let args, parseErr = null;
          try { args = JSON.parse(rawArgs); } catch (e) { parseErr = e; }
          const validArgs = args && typeof args === 'object' && !Array.isArray(args);
          let outText;
          if (parseErr || !validArgs) {
            // Don't silently run the tool with {} on malformed arguments — feed the
            // error back so the model corrects the call instead of grounding on a
            // wrong-scope result it believes is legitimate (#243B).
            outText = `Error: tool arguments were not a valid JSON object: ${String(rawArgs).slice(0, 200)}`;
          } else {
            ({ text: outText } = await runTool(tc.function && tc.function.name, args));
          }
          toolMsgs.push({ role: 'tool', tool_call_id: tc.id, content: outText });
        }
        messages = [...messages, { role: 'assistant', content: msg.content || null, tool_calls: msg.tool_calls }, ...toolMsgs];
      }
    } else {
      // #223: Claude egresses to api.anthropic.com (no loopback override), so an
      // air-gapped run is blocked unconditionally here.
      assertLocalOnly('AI Overview (cloud)');
      // Honor the forwarded key (--api-key / claude.txt), not just the env var —
      // previously the Claude branch ignored apiKey and hard-required the env,
      // so a --api-key-only setup failed Overview while Chat/Analyze worked.
      const key = apiKey || process.env.ANTHROPIC_API_KEY;
      if (!key) {
        throw new Error('AI Overview needs an Anthropic API key — set ANTHROPIC_API_KEY, pass --api-key, create claude.txt, or run an air-gapped overview with a local --model <gguf>.');
      }
      const Anthropic = (await import('@anthropic-ai/sdk')).default;
      const anthropic = new Anthropic({ apiKey: key });

      let messages = [{ role: 'user', content: aiOverviewPrompt(grounding) }];
      for (let turn = 0; turn < MAX_OVERVIEW_TURNS; turn++) {
        const response = await anthropic.messages.create({
          model: useModel, max_tokens: 4096, messages, tools: sdkTools,
        });
        if (response.usage) {
          usage.input_tokens += response.usage.input_tokens || 0;
          usage.output_tokens += response.usage.output_tokens || 0;
        }
        checkBudget();

        // Final prose = the latest text the model emits (the closing turn).
        const text = response.content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
        if (text) prose = text;

        if (response.stop_reason !== 'tool_use') break;

        const toolResults = [];
        for (const tu of response.content.filter(b => b.type === 'tool_use')) {
          const { text: outText, isError } = await runTool(tu.name, tu.input);
          toolResults.push({ type: 'tool_result', tool_use_id: tu.id, content: outText, ...(isError ? { is_error: true } : {}) });
        }
        messages = [...messages,
          { role: 'assistant', content: response.content },
          { role: 'user', content: toolResults }];
      }
    }

    if (!prose) throw new Error('AI Overview produced no prose (empty model output).');
    const { usd } = estimateCost(useModel, usage);
    return { prose, costUsd: Number.isFinite(usd) ? usd : null, usage };
  };

  // Bound the whole run by wall clock; cleanup tears down the client + subprocess.
  let timer;
  const timeout = new Promise((_, rej) => {
    timer = setTimeout(() => rej(new Error(
      `AI Overview timed out (${Math.round(timeoutMs / 60000)} min). Very large indexes may need a longer --timeout.`)), timeoutMs);
  });

  try {
    return await Promise.race([loop(), timeout]);
  } finally {
    clearTimeout(timer);
    await cleanup();
  }
}
